import json

reads = data['reads']
facts = {}
for i, r in enumerate(reads):
    val = r.get('result')
    if isinstance(val, str):
        try:
            val = json.loads(val)
        except Exception:
            pass
    facts[f'read_{i}_api'] = r['api']
    facts[f'read_{i}_type'] = str(type(val))
    if isinstance(val, dict):
        facts[f'read_{i}_keys'] = list(val.keys())
        if 'song' in val:
            facts[f'read_{i}_song_keys'] = list(val['song'].keys()) if isinstance(val['song'], dict) else str(type(val['song']))
        if 'queue' in val:
            facts[f'read_{i}_queue_len'] = len(val['queue']) if isinstance(val['queue'], list) else None
    elif isinstance(val, list):
        facts[f'read_{i}_len'] = len(val)
        if val:
            facts[f'read_{i}_first_type'] = str(type(val[0]))
            if isinstance(val[0], dict):
                facts[f'read_{i}_first_keys'] = list(val[0].keys())

print(json.dumps({"queries": [], "facts": facts}))
